/bin/bash -c "python - <<'PY'
import cv2,numpy as np
im=cv2.imread('first_frame.png')[:,:,::-1]
# Show geometry in ramp ROI by thresholding values for likely cardboard (darker warm gray), produce row min/max where v<115 and saturation low
for y in range(240,440,10):
 xs=[]
 for x in range(560,1210):
  p=im[y,x].astype(float); v=p.mean(); s=p.max()-p.min()
  if v<118 and s<35 and p[2]<p[0]+8: xs.append(x)
 if xs:
  print(y,min(xs),max(xs),len(xs))
PY"
